    public static function entityPermissions(): array
    {
        $permissions = array_map(static fn (array $record): array => $record['permissions'], self::recordDefinitions());
        foreach ($permissions as $type => &$required) {
            if (str_starts_with($type, 'supplier_award') || str_starts_with($type, 'procurement_award')) { $required = ['procurement.supplier_proposals.view', 'procurement.proposal_decisions.view']; }
            elseif (str_starts_with($type, 'procurement_cycle') || $type === 'procurement_process_event') { $required = ['procurement.dashboard.view']; }
            elseif (str_starts_with($type, 'supply_') || $type === 'purchase_order_promise_version' || $type === 'sent_purchase_order_line_owner') { $required = ['procurement.purchase_orders.view']; }
        }
        unset($required);
        $permissions['crm_contact_identity'] = [];
        $permissions['crm_contact_point'] = [];
        return $permissions;
    }

