    public static function domainGates(): array
    {
        $gates = [];
        foreach (self::recordDefinitions() as $type => $record) {
            if (isset(self::availabilityDefinitions()[$type])) { continue; }
            $gates[$record['domain']] ??= [$record['module'], []];
            $gates[$record['domain']][1] = array_values(array_unique([...$gates[$record['domain']][1], ...self::entityPermissions()[$type]]));
        }
        $gates['crm_business'][1] = array_values(array_unique([...$gates['crm_business'][1], 'crm.contacts.view', 'crm.companies.view']));
        return $gates;
    }

