    public static function domainDefinitions(): array
    {
        $result = [];
        foreach (self::domainGates() as $domain => [$module]) {
            $types = array_keys(array_filter(self::recordDefinitions(), static fn (array $record): bool => $record['domain'] === $domain));
            $fields = array_values(array_unique(array_merge(...array_map(static fn (string $type): array => self::recordDefinitions()[$type]['fields'], $types))));
            $typeSchema = ['type' => 'string', 'enum' => $types];
            $id = ['type' => ['integer', 'string'], 'minimum' => 1, 'minLength' => 1, 'maxLength' => 36, 'pattern' => '^(?:[1-9][0-9]*|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}|[0-9A-HJKMNP-TV-Z]{26})$'];
            $fieldSchema = ['type' => ['array', 'null'], 'items' => ['type' => 'string', 'enum' => $fields]];
            $schema = static fn (array $properties): array => ['type' => 'object', 'properties' => $properties, 'required' => array_keys($properties), 'additionalProperties' => false];
            $schemas = ['read' => $schema(['entity_type' => $typeSchema, 'id' => $id, 'fields' => $fieldSchema]), 'search' => $schema(['entity_type' => $typeSchema, 'query' => ['type' => 'string', 'maxLength' => 200], 'project_id' => ['type' => ['integer', 'null'], 'minimum' => 1], 'limit' => ['type' => 'integer', 'minimum' => 1, 'maximum' => 20], 'fields' => $fieldSchema]), 'navigation' => $schema(['entity_type' => $typeSchema, 'id' => $id])];
            $fieldPermissions = [];
            foreach (array_intersect($fields, [...self::factFieldGroups()['money'], 'vat_rate', 'premium_ratio', 'median_variance_ratio', 'non_lowest_delta_percent']) as $field) { $fieldPermissions[$field] = match ($domain) { 'commercial_proposals_business' => ['commercial_proposals.amounts.view'], 'presale_estimates' => ['presale_estimates.amounts.view'], default => ['finance.view'] }; }
            $result[] = new AssistantDomainDefinition($domain, $module, $types[0], [], $fields, $schemas, array_keys($schemas), match ($domain) { 'procurement_business' => '/procurement', 'crm_business' => '/crm', 'contractor_marketplace' => '/dashboard/contractor-marketplace', 'sales_supplier_catalog' => '/suppliers', default => '/commercial-proposals' }, $domain, $types, $fieldPermissions, array_intersect_key(self::entityPermissions(), array_flip($types)));
        }
        return $result;
    }

