    public static function applyActorScope(string $type, Builder $query, User $actor, int $organizationId, AuthorizationService $authorization, AssistantDataAccessPolicy $policy): void
    {
        $table = $query->getModel()->getTable();
        if ($type === 'crm_timeline_event' || $type === 'crm_merge_event') {
            $types = $type === 'crm_merge_event' ? ['companies' => 'crm_company', 'contacts' => 'crm_contact'] : ['companies' => 'crm_company', 'contacts' => 'crm_contact', 'leads' => 'crm_lead', 'deals' => 'crm_deal', 'activities' => 'crm_activity'];
            $column = $type === 'crm_merge_event' ? 'master_id' : 'entity_id';
            $query->where(static function (Builder $scope) use ($types, $column, $actor, $organizationId, $policy, $table): void {
                $scope->whereRaw('1 = 0');
                foreach ($types as $nativeType => $parentType) {
                    $parents = $policy->entityQuery($actor, $organizationId, $parentType);
                    if ($parents === null) { continue; }
                    $parentTable = $parents->getModel()->getTable();
                    $scope->orWhere(static fn (Builder $branch): Builder => $branch->where($table.'.entity_type', $nativeType)->whereIn($table.'.'.$column, $parents->select($parentTable.'.id')));
                }
            });
        } elseif ($type === 'crm_contact_identity' || $type === 'crm_contact_point') {
            $query->where(static fn (Builder $scope): Builder => $scope->whereNotNull($table.'.company_id')->orWhereNotNull($table.'.contact_id'));
        }
    }

    public static function applyOrganizationScope(string $type, Builder $query, User $actor, int $organizationId, AuthorizationService $authorization, AssistantDataAccessPolicy $policy): bool
    {
        if ($organizationId < 1 || ! isset(self::customOrganizationScopes()[$type])) { return false; }
        if ($type === 'marketplace_contractor_profile') {
            SalesBusinessRagSource::applyMarketplaceNetwork($query, $organizationId);
            return true;
        }
        if ($type === 'marketplace_hiring_offer') {
            $table = $query->getModel()->getTable();
            $query->where(static fn (Builder $scope): Builder => $scope->where($table.'.hiring_organization_id', $organizationId)->orWhere($table.'.contractor_organization_id', $organizationId));
            return true;
        }
        return false;
    }

